// TASK-0042 — V1 Source Availability & Stale Index Foundation, product acceptance
// in real WebView2. No simulated DOM, no alternate renderer, no personal data: the
// tree under test was generated by task0042-seed-proof.py and dies with the proof
// root.
//
// Two phases, one REAL process restart between them (run by the .ps1):
//
//   phase 1  first Actualiser -> BASELINE_FULL, badge SYNCED; an unchanged
//            Actualiser -> INCREMENTAL no-op; one real change so the journal is
//            not empty; then THIS SCRIPT moves the whole root out of its path (on
//            disk, outside the product process) and ONE real Actualiser click
//            fails cleanly: the map that was loaded stays on screen, the badge
//            says UNAVAILABLE (« dernier index conservé »), the status line
//            explains, and revision / journal / projection / index id are exactly
//            what they were. The product read the badge back from the backend
//            (map_source_observation), it did not reopen the map.
//   phase 2  after the real restart, the source STILL absent: the map opens
//            without any source access, the badge still says UNAVAILABLE with the
//            very same persisted instant, nothing built by itself. THIS SCRIPT
//            puts the same folder back; one real Actualiser -> INCREMENTAL no-op,
//            same revision, badge SYNCED, journal untouched. Last, the folder is
//            deleted and recreated (a DIFFERENT root at the same path): the real
//            Actualiser refuses it (SOURCE_CHANGED), the old Index stays, and
//            Reconstruire — the explicit gesture — accepts it (SYNCED).
//
// Every filesystem change is made by THIS script directly on disk, outside the
// product process, between two real clicks.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFile, writeFile, rm, rename, mkdir, stat } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const phase = Number(process.argv[4]);
assert(/^task0042-[a-f0-9]+$/.test(variant));
assert(phase === 1 || phase === 2);

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, absolutePath } = seed;
const proofRoot = join(".filetopo-sandbox", variant);
const root = absolutePath; // used only by THIS script's own fs calls — never sent into the page.
const held = `${root}-deplace`;

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
// Every `map_*` IPC round trip the PRODUCT itself makes, observed on the wire
// through CDP's Network domain, in order. (The harness's own `invoke` calls go
// through Runtime.evaluate and are recorded apart, so they can never be mistaken
// for what the product did.) The response body of a custom-protocol request is not
// retrievable through CDP: the wire gives the command, its order and whether it
// completed; the closed report fields are read from the product's own UI.
const wireRequests = new Map();
const wireStatus = new Map();
const wireCalls = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.method === "Network.requestWillBeSent") {
    const url = event.params.request.url;
    const m = /\/(map_[a-z_]+)(?:[?#].*)?$/.exec(url);
    if (m && /ipc/.test(url)) wireRequests.set(event.params.requestId, m[1]);
  } else if (event.method === "Network.responseReceived" && wireRequests.has(event.params.requestId)) {
    // Tauri answers an `Err` on the same custom protocol; the outcome travels in
    // the `Tauri-Response` header (`ok` | `error`) next to the HTTP status.
    const headers = event.params.response.headers ?? {};
    const outcome = Object.entries(headers).find(([name]) => name.toLowerCase() === "tauri-response")?.[1];
    wireStatus.set(event.params.requestId, event.params.response.status === 200 && outcome !== "error" ? 200 : 500);
  } else if (event.method === "Network.loadingFinished" && wireRequests.has(event.params.requestId)) {
    const id = event.params.requestId;
    wireCalls.push({ command: wireRequests.get(id), ok: (wireStatus.get(id) ?? 200) === 200 });
    wireRequests.delete(id);
  } else if (event.method === "Network.loadingFailed" && wireRequests.has(event.params.requestId)) {
    wireCalls.push({ command: wireRequests.get(event.params.requestId), ok: false });
    wireRequests.delete(event.params.requestId);
  }
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ??
        r.exceptionDetails.exception?.value ??
        JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const exposedPayloads = [];
// The harness's own reads (never a product click). Only `map_open`,
// `map_source_observation`, `map_view` and `map_change_journal` are used — all of
// them read FileTopo's own local state and none of them touches the source.
const invoke = async (command, args = {}) => {
  exposedPayloads.push(JSON.stringify(args));
  const result = await evaluate(
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`,
  );
  exposedPayloads.push(JSON.stringify(result ?? null));
  return result;
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");
await send("Network.enable", { maxTotalBufferSize: 64 * 1024 * 1024, maxResourceBufferSize: 16 * 1024 * 1024 });

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
const jargon = [
  "stable_key",
  "stableKey",
  "identity_provenance",
  "identityProvenance",
  "SYS1:",
  "PFv1:",
  "PATH_FALLBACK",
  "fileId",
  "file_id",
  "volumeSerial",
  "volume_serial",
];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal identity jargon "${word}" leaked into ${where}`);
}
function assertNoPathLeak(text, where) {
  for (const path of [root, held]) {
    const escaped = path.split("\\").join("\\\\");
    assert(!text.includes(path) && !text.includes(escaped), `absolute path leaked into ${where}`);
  }
  assert(!/os error/i.test(text), `a raw OS message leaked into ${where}`);
}
async function assertConfidential() {
  const bodyText = await evaluate("document.body.textContent");
  assertNoPathLeak(bodyText, "page body text");
  assertNoJargon(bodyText, "page body text");
  for (const payload of exposedPayloads) {
    assertNoPathLeak(payload, "an invoke payload");
    assertNoJargon(payload, "an invoke payload");
  }
}
const exists = async (path) => {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
};

// ---- what the real screen shows ------------------------------------------------
async function waitForAppReady() {
  await until(`!!document.querySelector('[data-testid="details-panel-toggle"]')`);
  await until(`!!document.querySelector('[data-testid="change-journal"]')`);
  await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
}
const revisionExpression = `(() => { const t = document.querySelector('[data-testid="report-brain"]')?.textContent ?? ''; const m = /révision (\\d+)/.exec(t); return m ? Number(m[1]) : -1; })()`;
const currentRevision = () => evaluate(revisionExpression);
const uiModeAttribute = () =>
  evaluate(`document.querySelector('[data-testid="application-mode"]')?.getAttribute('data-application-mode') ?? null`);
const uiSummaryText = () => evaluate(`document.querySelector('[data-testid="change-summary"]')?.textContent ?? ''`);
const uiSummary = async () =>
  JSON.parse(await evaluate(`document.querySelector('[data-testid="change-summary"]')?.getAttribute('data-summary') ?? 'null'`));
const statusText = () => evaluate(`document.querySelector('.app__status')?.textContent ?? ''`);
const composedTotal = () => evaluate(`document.querySelector('[data-testid="composed-total"]')?.textContent ?? ''`);
const reportBrain = () => evaluate(`document.querySelector('[data-testid="report-brain"]')?.textContent ?? ''`);
const badge = () =>
  evaluate(`(() => {
    const e = document.querySelector('[data-testid="source-observation"]');
    if (!e) return null;
    return {
      state: e.getAttribute('data-state'),
      reason: e.getAttribute('data-reason'),
      persisted: e.getAttribute('data-persisted'),
      role: e.getAttribute('role'),
      text: e.textContent,
    };
  })()`);
const waitBadge = (state, limit = 30000) =>
  until(`document.querySelector('[data-testid="source-observation"]')?.getAttribute('data-state') === ${JSON.stringify(state)}`, limit);

/**
 * One real click on Actualiser (or Reconstruire). Resolves once the product has
 * answered the build call and settled. It does NOT assert success: a refusal is a
 * legitimate outcome here, and `ok` says which one it was.
 */
async function lifecycle(testid) {
  const from = wireCalls.length;
  await activate(`[data-testid="${testid}"]`);
  const command = testid === "lifecycle-rebuild" ? "map_rebuild" : "map_refresh";
  const start = Date.now();
  while (!wireCalls.slice(from).some((call) => call.command === command)) {
    if (Date.now() - start > 120000) throw new Error(`timeout waiting for ${command} on the wire`);
    await pause(100);
  }
  await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled`);
  await pause(600);
  const calls = wireCalls.slice(from);
  return {
    calls,
    ok: calls.find((call) => call.command === command).ok,
    commands: calls.map((call) => call.command),
  };
}
const refresh = () => lifecycle("lifecycle-refresh");
const rebuild = () => lifecycle("lifecycle-rebuild");

// ---- backend reads (local state only) ------------------------------------------
async function apiPage() {
  const page = await invoke("map_change_journal", { brainId, natures: [], after: null, limit: 50 });
  assert.equal(page.brainId, brainId);
  return page;
}
const flagsOf = (page) => page.items.map((e) => [e.eventId, e.nature, e.seen]);
const digest = (text) => createHash("sha256").update(text).digest("hex");
async function projectionDigest() {
  return digest(JSON.stringify(await invoke("map_view", { brainId })));
}
async function openJournal() {
  const open = await evaluate(`document.querySelector('[data-testid="journal-toggle"]').getAttribute('aria-expanded') === 'true'`);
  if (!open) await activate('[data-testid="journal-toggle"]');
  await until(`!!document.querySelector('[data-testid="journal-total"]')`);
}
const uiEventCount = () => evaluate(`document.querySelectorAll('[data-testid="journal-event"]').length`);
async function snapshot() {
  const opened = await invoke("map_open", { brainId });
  const page = await apiPage();
  return {
    revision: opened.revision,
    indexId: opened.indexId,
    sourceRead: opened.sourceRead,
    nodeCount: opened.nodeCount,
    observation: opened.sourceObservation,
    flags: flagsOf(page),
    total: page.total,
    unseenTotal: page.unseenTotal,
    deleted: page.items.filter((e) => e.nature === "DELETED").length,
    projection: await projectionDigest(),
  };
}
// What must NOT change when the source is away: everything except the observation.
const sameIndex = (a, b) =>
  a.revision === b.revision &&
  a.indexId === b.indexId &&
  a.nodeCount === b.nodeCount &&
  JSON.stringify(a.flags) === JSON.stringify(b.flags) &&
  a.total === b.total &&
  a.unseenTotal === b.unseenTotal &&
  a.deleted === b.deleted &&
  a.projection === b.projection;

const results = {};
await waitForAppReady();

if (phase === 1) {
  // ---- 1 — baseline: BASELINE_FULL, and the badge says SYNCED -------------------
  const first = await refresh();
  assert(first.ok, "the first Actualiser succeeds");
  await waitBadge("SYNCED");
  const baselineBadge = await badge();
  results.baselineIsSynced =
    (await uiModeAttribute()) === "BASELINE_FULL" &&
    baselineBadge.state === "SYNCED" &&
    baselineBadge.reason === "" &&
    baselineBadge.role === "status" &&
    /À jour à la dernière vérification/.test(baselineBadge.text);
  assert(results.baselineIsSynced, "the baseline is SYNCED and says « à la dernière vérification »");
  const baselineRevision = await currentRevision();

  // ---- 2 — an unchanged Actualiser: incremental no-op, still SYNCED --------------
  const quiet = await refresh();
  assert(quiet.ok);
  results.unchangedIsSyncedNoOp =
    (await uiModeAttribute()) === "INCREMENTAL" &&
    (await uiSummaryText()) === "Aucun changement détecté." &&
    (await currentRevision()) === baselineRevision &&
    (await badge()).state === "SYNCED";
  assert(results.unchangedIsSyncedNoOp, "an unchanged Actualiser stays SYNCED on the same revision");

  // ---- 3 — one real change, so the journal is not empty ---------------------------
  await writeFile(join(root, "arrivee.txt"), "synthetique — arrivee\n", "utf8");
  const changed = await refresh();
  assert(changed.ok);
  const summary = await uiSummary();
  assert.equal(summary.created, 1);
  assert.equal(summary.total, 1);
  const beforeAbsence = await snapshot();
  assert.equal(beforeAbsence.observation.state, "SYNCED");
  assert.equal(beforeAbsence.observation.lastSuccessfulRevision, beforeAbsence.revision);
  await openJournal();
  const journalRowsBefore = await uiEventCount();
  assert(journalRowsBefore >= 1, "the journal shows the change");
  const shownBefore = {
    total: await composedTotal(),
    report: await reportBrain(),
  };

  // ---- 4 — THIS SCRIPT moves the whole root out of its path ----------------------
  await rename(root, held);
  assert(!(await exists(root)), "the source really is gone from its path");
  assert(await exists(held), "the folder is only moved, never deleted");
  const wireBefore = wireCalls.length;
  const failed = await refresh();
  results.actualiserFailedCleanly = failed.ok === false;
  assert(results.actualiserFailedCleanly, "the real Actualiser is refused when the root is absent");

  // The badge follows the backend: it read `map_source_observation`, it did not
  // reopen the map, and it did not scan again.
  await waitBadge("UNAVAILABLE");
  const failureCommands = wireCalls.slice(wireBefore).map((call) => call.command);
  results.badgeReadFromBackendWithoutReopening =
    failureCommands.includes("map_source_observation") &&
    !failureCommands.includes("map_open") &&
    !failureCommands.includes("map_rebuild") &&
    failureCommands.filter((c) => c === "map_refresh").length === 1;
  assert(results.badgeReadFromBackendWithoutReopening, `after the failure the product asks the backend (${failureCommands.join(",")})`);

  const unavailable = await badge();
  results.badgeSaysUnavailable =
    unavailable.state === "UNAVAILABLE" &&
    unavailable.reason === "ROOT_NOT_FOUND" &&
    unavailable.role === "alert" &&
    unavailable.persisted === "true" &&
    /Source indisponible — dernier index conservé/.test(unavailable.text) &&
    /le dossier est introuvable/.test(unavailable.text) &&
    /Dernière observation/.test(unavailable.text) &&
    !/à jour/i.test(unavailable.text);
  assert(results.badgeSaysUnavailable, "the badge says UNAVAILABLE in words, with a reason and the last observation");

  // The map that was loaded is STILL ON SCREEN, exactly as it was.
  results.mapStaysOnScreen =
    (await composedTotal()) === shownBefore.total &&
    (await reportBrain()) === shownBefore.report &&
    (await currentRevision()) === beforeAbsence.revision &&
    /Échec/.test(await statusText()) &&
    /reste disponible/.test(await statusText()) &&
    (await evaluate(`!!document.querySelector('[data-testid="details-panel-toggle"]')`));
  assert(results.mapStaysOnScreen, "the loaded map, its report and its revision stay on screen after the failure");

  // A local action on the Index stays available: the journal panel still works.
  await openJournal();
  results.localActionsStillWork = (await uiEventCount()) === journalRowsBefore;
  assert(results.localActionsStillWork, "the journal, a local action, is still readable");

  // Nothing but the observation moved.
  const afterAbsence = await snapshot();
  results.indexUntouchedByTheAbsence = sameIndex(beforeAbsence, afterAbsence) && afterAbsence.sourceRead === false;
  assert(results.indexUntouchedByTheAbsence, "revision, index id, corpus, journal, seen state and projection are unchanged");
  results.noDeletionInvented = afterAbsence.deleted === beforeAbsence.deleted && afterAbsence.total === beforeAbsence.total;
  assert(results.noDeletionInvented, "no DELETED event was invented");
  assert.equal(afterAbsence.observation.state, "UNAVAILABLE");
  assert.equal(afterAbsence.observation.lastSuccessfulRevision, beforeAbsence.revision, "the last synchronisation is remembered");

  await assertConfidential();
  results.noAbsolutePathOrIdentityLeak = true;
  results.snapshot = { ...afterAbsence, shownBefore };
  results.baselineRevision = baselineRevision;
} else {
  // ---- phase 2: after a REAL process restart, the source STILL absent -------------
  const before = JSON.parse(await readFile(join(proofRoot, "phase1.json"), "utf8")).snapshot;
  results.sourceStillAbsentAtRestart = !(await exists(root)) && (await exists(held));
  assert(results.sourceStillAbsentAtRestart, "the source is still away from its path when the product restarts");
  await until(`${revisionExpression} >= 0`);
  await waitBadge("UNAVAILABLE");

  // Opening never touched the source and never built anything by itself.
  results.nothingBuiltAtStartup = !wireCalls.some((call) => call.command === "map_refresh" || call.command === "map_rebuild");
  assert(results.nothingBuiltAtStartup, "no build ran by itself at start-up");
  const reopened = await badge();
  results.openedWithoutTheSource =
    reopened.state === "UNAVAILABLE" &&
    reopened.reason === "ROOT_NOT_FOUND" &&
    /Source indisponible — dernier index conservé/.test(reopened.text) &&
    !(await exists(root));
  assert(results.openedWithoutTheSource, "Ouvrir shows the map and the persisted UNAVAILABLE with the source still absent");
  const restarted = await snapshot();
  results.sameIndexAfterRestart = sameIndex(before, restarted) && restarted.sourceRead === false;
  assert(results.sameIndexAfterRestart, "the same Index, revision, journal, seen state and projection after a real restart");
  results.sameObservationAfterRestart =
    restarted.observation.state === "UNAVAILABLE" &&
    restarted.observation.observedUnixMs === before.observation.observedUnixMs &&
    restarted.observation.lastSuccessfulRevision === before.observation.lastSuccessfulRevision &&
    restarted.observation.persisted === true;
  assert(results.sameObservationAfterRestart, "the observation was persisted: same state, same instant, not regenerated");
  assert.equal(await currentRevision(), before.revision);
  assert(!(await exists(root)), "reading did not bring the source back, nor look for it");

  // ---- the SAME folder comes back; one real Actualiser ---------------------------
  await rename(held, root);
  assert(await exists(root));
  const recovered = await refresh();
  assert(recovered.ok, "the Actualiser succeeds once the folder is back");
  await waitBadge("SYNCED");
  const synced = await badge();
  const afterRecovery = await snapshot();
  results.recoveryIsIncrementalNoOp =
    (await uiModeAttribute()) === "INCREMENTAL" &&
    (await uiSummaryText()) === "Aucun changement détecté." &&
    (await currentRevision()) === before.revision &&
    synced.state === "SYNCED" &&
    /À jour à la dernière vérification/.test(synced.text) &&
    afterRecovery.observation.state === "SYNCED" &&
    afterRecovery.observation.lastSuccessfulRevision === before.revision;
  assert(results.recoveryIsIncrementalNoOp, "the same folder back: incremental no-op, same revision, SYNCED");
  results.recoveryInventedNothing = sameIndex(before, afterRecovery);
  assert(results.recoveryInventedNothing, "not one event, row or revision was invented by the round trip");

  // ---- a DIFFERENT root at the same path: refused, and Reconstruire accepts it ----
  await rm(root, { recursive: true, force: true });
  await mkdir(join(root, "dossier", "sous"), { recursive: true });
  await mkdir(join(root, "vide"));
  for (const name of ["a-modifier.txt", "a-supprimer.txt", "stable-0.txt", "stable-1.txt", "stable-2.txt", "arrivee.txt", "dossier/enfant.txt", "dossier/sous/profond.txt"]) {
    await writeFile(join(root, name), "synthetique — meme contenu, autre dossier\n", "utf8");
  }
  const replaced = await refresh();
  assert.equal(replaced.ok, false, "a root replaced at the same path is refused, never resumed silently");
  await waitBadge("SOURCE_CHANGED");
  const changedBadge = await badge();
  const afterReplacement = await snapshot();
  results.replacedRootIsSourceChanged =
    changedBadge.state === "SOURCE_CHANGED" &&
    changedBadge.reason === "ROOT_IDENTITY_CHANGED" &&
    /Source remplacée ou différente — dernier index conservé/.test(changedBadge.text) &&
    /Reconstruire/.test(changedBadge.text) &&
    sameIndex(before, afterReplacement) &&
    (await currentRevision()) === before.revision &&
    /Échec/.test(await statusText());
  assert(results.replacedRootIsSourceChanged, "SOURCE_CHANGED, the old Index served, no mass creation or deletion");

  const accepted = await rebuild();
  assert(accepted.ok, "Reconstruire is the explicit gesture that accepts the new root");
  await waitBadge("SYNCED");
  results.reconstruireAcceptsTheNewRoot =
    (await uiModeAttribute()) === "EXPLICIT_REBUILD_FULL" && (await badge()).state === "SYNCED";
  assert(results.reconstruireAcceptsTheNewRoot, "Reconstruire accepts the replaced root and the badge returns to SYNCED");

  await assertConfidential();
  results.noAbsolutePathOrIdentityLeak = true;
}

await writeFile(join(proofRoot, `phase${phase}.json`), JSON.stringify(results));
console.log(JSON.stringify({ ok: true, phase }));

assert.equal(fatal.length, 0, `fatal page/console errors`);
await writeFile(join(proofRoot, `phase${phase}-fatal-count.json`), JSON.stringify(fatal.length));
ws.close();
